(7551090, 1209675, 24983, '<td valign="top">//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1209675#</td>', '//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1209675#', '2018-01-05 00:47:22.000000', NULL, 1),
(7551096, 1209984, 30861, '<td valign="top">Beautiful, moody image, but I can''t see it as "abstract" in any meaningful way. Even in the pure sense of the word "abstraction" (reducing a thing to its basic elements) this doesn''t work for the challenge, at least for me. But what a gorgeous shot. The metallic tone of the gondolas is sublime.</td>', 'Beautiful, moody image, but I can''t see it as "abstract" in any meaningful way. Even in the pure sense of the word "abstraction" (reducing a thing to its basic elements) this doesn''t work for the challenge, at least for me. But what a gorgeous shot. The metallic tone of the gondolas is sublime.', '2018-01-05 01:11:45.000000', NULL, 1),
(7551154, 1209550, 86447, '<td valign="top">Great Grate!</td>', 'Great Grate!', '2018-01-05 14:24:13.000000', NULL, 1),
(7551186, 1209984, 97225, '<td valign="top">Although this is a pleasing image it doesn''t meet the abstract part of the theme.</td>', 'Although this is a pleasing image it doesn''t meet the abstract part of the theme.', '2018-01-05 18:42:29.000000', NULL, 1),
(7551217, 1209997, 181814, '<td valign="top">Fascinating photograph, I like the square crop, and the composition is excellent as is the exposure.</td>', 'Fascinating photograph, I like the square crop, and the composition is excellent as is the exposure.', '2018-01-05 21:32:14.000000', NULL, 1),
(7551218, 1209530, 181814, '<td valign="top">Terrific close-up of a withered piece of wood. Composition, focus, and exposure are well done.</td>', 'Terrific close-up of a withered piece of wood. Composition, focus, and exposure are well done.', '2018-01-05 21:33:56.000000', NULL, 1),
(7551220, 1210006, 181814, '<td valign="top">Definitely abstract, I have no idea what it is, but it does look nice.</td>', 'Definitely abstract, I have no idea what it is, but it does look nice.', '2018-01-05 21:35:28.000000', NULL, 1),
(7551222, 1209877, 181814, '<td valign="top">A unique photograph to say the least. This picture is one of my favorites in the contest; I find it fascinating to view.</td>', 'A unique photograph to say the least. This picture is one of my favorites in the contest; I find it fascinating to view.', '2018-01-05 21:38:38.000000', NULL, 1),
(7551225, 1209989, 159132, '<td valign="top">Interesting visual, though a bit concrete (vs. abstract)</td>', 'Interesting visual, though a bit concrete (vs. abstract)', '2018-01-05 22:57:54.000000', NULL, 1),
(7551226, 1210020, 159132, '<td valign="top">Excellent job making something we all know (and love) into an abstract concept. One suggestion - it looks like there is a tiny peak in the lower left. I wish the shadow of the peak (which is barely noticeable) was slightly more distinct. 6</td>', 'Excellent job making something we all know (and love) into an abstract concept. One suggestion - it looks like there is a tiny peak in the lower left. I wish the shadow of the peak (which is barely noticeable) was slightly more distinct. 6', '2018-01-05 23:00:10.000000', NULL, 1),
(7551227, 1209968, 159132, '<td valign="top">Excellent abstract. Leaves?</td>', 'Excellent abstract. Leaves?', '2018-01-05 23:00:26.000000', NULL, 1),
(7551228, 1210006, 159132, '<td valign="top">I like symmetry; looks more like a texture though</td>', 'I like symmetry; looks more like a texture though', '2018-01-05 23:00:49.000000', NULL, 1),
(7551230, 1209997, 159132, '<td valign="top">Beautiful. Clock? Petri dish? Then noticing the cross-hatch background. Excellent. 7</td>', 'Beautiful. Clock? Petri dish? Then noticing the cross-hatch background. Excellent. 7', '2018-01-05 23:01:52.000000', NULL, 1),
(7551231, 1209947, 159132, '<td valign="top">Excellent optical effect and visual. Not sure it is really abstract IMO</td>', 'Excellent optical effect and visual. Not sure it is really abstract IMO', '2018-01-05 23:02:56.000000', NULL, 1),
(7551232, 1209550, 159132, '<td valign="top">Nice work finding an abstract in such a concrete thing</td>', 'Nice work finding an abstract in such a concrete thing', '2018-01-05 23:04:43.000000', NULL, 1),
(7551233, 1209984, 159132, '<td valign="top">Excellent presentation - something quite concrete yet you brought out an abstract quality</td>', 'Excellent presentation - something quite concrete yet you brought out an abstract quality', '2018-01-05 23:05:37.000000', NULL, 1),
(7551234, 1209675, 159132, '<td valign="top">Excellent presentation. I might have downplayed the railing across the lower row. That brought the concrete out a bit too much for me. 6</td>', 'Excellent presentation. I might have downplayed the railing across the lower row. That brought the concrete out a bit too much for me. 6', '2018-01-05 23:07:54.000000', NULL, 1),
(7551235, 1209976, 159132, '<td valign="top">I love this as an abstract. I can almost sense a face in the right side swirl. But so totally Dali-esque as to be true to the abstract theme</td>', 'I love this as an abstract. I can almost sense a face in the right side swirl. But so totally Dali-esque as to be true to the abstract theme', '2018-01-05 23:09:05.000000', NULL, 1),
(7551236, 1210013, 159132, '<td valign="top">Lovely treatment, capture, and PP. A tad too concrete for me to score higher</td>', 'Lovely treatment, capture, and PP. A tad too concrete for me to score higher', '2018-01-05 23:09:46.000000', NULL, 1),
(7551237, 1210002, 159132, '<td valign="top">Nicely done. A musical quality for me.</td>', 'Nicely done. A musical quality for me.', '2018-01-05 23:10:07.000000', NULL, 1),
(7551238, 1210009, 159132, '<td valign="top">Wow. Totally artistic. High score. I might have worked in PP to under-emphasize the middle area to highlight the top and/or circular region.</td>', 'Wow. Totally artistic. High score. I might have worked in PP to under-emphasize the middle area to highlight the top and/or circular region.', '2018-01-05 23:11:26.000000', NULL, 1),
